    'invariance-couleur-profils-wiener-bruit': 'study_noise_profile_color_invariance.py',
    'transfert-photo-profils-bruit': 'study_noise_profile_photo_transfer.py',
}


def source_encoding(source, expected):
    for name, encoded in (('utf8_lf', source.encode('utf-8')),
                          ('utf8_crlf', source.replace('\r\n', '\n').replace('\n', '\r\n').encode('utf-8'))):
        if hashlib.sha256(encoded).hexdigest() == expected:
            return name
    raise ValueError('Archived source does not match recorded byte hash')


def budgets(node):
    count = 0
    if isinstance(node, dict):
        if isinstance(node.get('full'), dict) and all(k in node['full'] for k in ('mse', 'signal_distortion', 'residual_noise', 'cross')):
            f = node['full']; arrays = [np.asarray(f[k], dtype=float) for k in ('mse', 'signal_distortion', 'residual_noise', 'cross')]
            if any(a.shape != (3,) or not np.isfinite(a).all() for a in arrays):
                raise ValueError('Invalid saved budget')
            if not np.allclose(arrays[0], arrays[1]+arrays[2]+arrays[3], atol=1e-10, rtol=1e-10):
                raise ValueError('Saved error decomposition does not close')
            if 'bands' in node:
                for key in f:
                    if key in ('mse', 'signal_distortion', 'residual_noise', 'cross'):
                        total = sum(np.asarray(b['contributions'][key]) for b in node['bands'].values())
                        if not np.allclose(total, f[key], atol=1e-10, rtol=1e-10):
                            raise ValueError('Saved area-weighted band budgets do not close')
            count += 1
        for value in node.values():
            if isinstance(value, (dict, list)):
                count += budgets(value)
    elif isinstance(node, list):
        for value in node:
            if isinstance(value, (dict, list)):
                count += budgets(value)
    return count


def run():
    raw = ROOT/'docs/validation/raw'
    archive_paths = sorted(raw.glob('archive-sources-contexte-wiener-v001-*.json'))
    archived = {}
    for path in archive_paths:
        for record in json.loads(path.read_text(encoding='utf-8'))['records']:
            archived[record['runner_sha256']] = record['runner_source']
    records = []
    for prefix, runner in RUNNERS.items():
        for path in sorted(raw.glob(prefix+'-v*-20261026T*.json')):
            data = json.loads(path.read_text(encoding='utf-8')); expected = data['runner_sha256']
            source = data.get('runner_source') or archived.get(expected)
            source_location = 'embedded_or_archived'
            if source is None:
                source = (ROOT/'tests'/runner).read_text(encoding='utf-8'); source_location = 'unchanged_current_file'
            encoding = source_encoding(source, expected)
            dependencies = []
            for name, metadata in data.get('dependencies', {}).items():
                if isinstance(metadata, dict):
                    source_encoding(metadata['source'], metadata['sha256'])
                    location = 'embedded'
                else:
                    if sha256(ROOT/'tests'/name) != metadata:
                        raise ValueError('Unarchived dependency has changed: '+name)
                    location = 'unchanged_current_file'
                dependency = dict(name=name, source=location)
                if location == 'unchanged_current_file':
                    dependency.update(sha256=metadata, source_snapshot=(ROOT/'tests'/name).read_text(encoding='utf-8'))
                    dependency['byte_encoding'] = source_encoding(dependency['source_snapshot'], metadata)
                dependencies.append(dependency)
            records.append(dict(path=str(path), sha256=sha256(path),
                runner_source=source_location, runner_byte_encoding=encoding,
                current_runner_snapshot=source if source_location=='unchanged_current_file' else None,
                dependencies=dependencies, saved_budget_count=budgets(data)))
    if len(records) != 16:
        raise ValueError(f'Expected16 completed campaign proofs,found{len(records)}')
    now = datetime.now(timezone.utc)
    output = raw/f"audit-integrite-campagne-wiener-bruit-v002-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result = dict(schema_version=1, data_version=2, completed_at_utc=now.isoformat(),
        runner_sha256=sha256(Path(__file__)), runner_source=Path(__file__).read_text(encoding='utf-8'),
        branch=git('branch', '--show-current'), records=records,
        source_archive_parents=[dict(path=str(p), sha256=sha256(p)) for p in archive_paths],
        production_diff=git('diff', '--name-only', '--', 'src').splitlines(),
        rules='Verify actual archived source bytes (LF orCRLF explicitly),dependencies,fullsavedMSEdecomposition and areaweighted bands. No re-render or modification of any priorJSON.16completedproofs,photo version2 intentionally repeats version1 noise;offset/sigma/cropstates not independentcaptures.',
        limitations='Integrity/provenance consistency audit,not scientificquality validation or proofabsenceofalgorithmicbugs. Only explicitly recorded direct dependencies checked,not complete transitive Python/environment closure. Verified currentfile fallbacks now archived beforefuturechanges. Production diff read-only,doesnotidentifyownershipofotherpre-existingchanges.')
    with output.open('x', encoding='utf-8') as handle:
        json.dump(result, handle, ensure_ascii=False, indent=1, allow_nan=False)
    print(output)
    print(len(records), 'proofs;', sum(r['saved_budget_count'] for r in records), 'budgets checked')


if __name__ == '__main__':
    run()

