def decompose(output,signal,residual,truth):
    arrays=[np.asarray(v,dtype=float) for v in (output,signal,residual,truth)]
    if any(v.shape!=(3,24,24) or not np.isfinite(v).all() for v in arrays):raise ValueError('Finite three-plane24 arrays required')
    output,signal,residual,truth=arrays
    if not np.allclose(output,signal+residual,atol=1e-10,rtol=1e-10):raise ValueError('Invalid linear transport')
    error=output-truth;distortion=signal-truth
    terms=dict(mse=error*error,signal_distortion=distortion*distortion,residual_noise=residual*residual,cross=2*distortion*residual)
    if not np.allclose(terms['mse'],terms['signal_distortion']+terms['residual_noise']+terms['cross'],atol=1e-10,rtol=1e-10):raise ValueError('Invalid error budget')
    result=dict(full={k:np.mean(v,axis=(1,2)).tolist() for k,v in terms.items()},
        columns={k:np.mean(v,axis=1).tolist() for k,v in terms.items()},
        mean_error_columns=np.mean(error,axis=1).tolist(),mean_signal_bias_columns=np.mean(distortion,axis=1).tolist(),
        mean_noise_columns=np.mean(residual,axis=1).tolist(),bands={})
