def bands():
    x=np.arange(20,44);distance=np.abs(x-31.5)
    columns={'crossing':distance<2.5,'nearby':(distance>=2.5)&(distance<6.5),'farther':distance>=6.5}
    return {k:np.broadcast_to(v[None,:],(24,24)).copy() for k,v in columns.items()}


def decompose(output,signal,residual,truth):
    arrays=[np.asarray(v,dtype=float) for v in (output,signal,residual,truth)]
    if any(v.shape!=(3,24,24) or not np.isfinite(v).all() for v in arrays):raise ValueError('Finite three-plane24 arrays required')
    output,signal,residual,truth=arrays
    if not np.allclose(output,signal+residual,atol=1e-10,rtol=1e-10):raise ValueError('Invalid linear transport')
    error=output-truth;distortion=signal-truth
    terms=dict(mse=error*error,signal_distortion=distortion*distortion,residual_noise=residual*residual,cross=2*distortion*residual)
    if not np.allclose(terms['mse'],terms['signal_distortion']+terms['residual_noise']+terms['cross'],atol=1e-10,rtol=1e-10):raise ValueError('Invalid error budget')
    result=dict(full={k:np.mean(v,axis=(1,2)).tolist() for k,v in terms.items()},
        columns={k:np.mean(v,axis=1).tolist() for k,v in terms.items()},
        mean_error_columns=np.mean(error,axis=1).tolist(),mean_signal_bias_columns=np.mean(distortion,axis=1).tolist(),
        mean_noise_columns=np.mean(residual,axis=1).tolist(),bands={})
    for name,mask in bands().items():
        count=int(mask.sum());density={k:np.mean(v[:,mask],axis=1).tolist() for k,v in terms.items()}
        result['bands'][name]=dict(pixels=count,means=density,
            contributions={k:(np.asarray(values)*count/576).tolist() for k,values in density.items()},
            mean_error=np.mean(error[:,mask],axis=1).tolist())
    for k in terms:
        total=sum(np.asarray(b['contributions'][k]) for b in result['bands'].values())
        if not np.allclose(total,result['full'][k],atol=1e-10):raise ValueError('Band partition does not reproduce full error')
    return result


def verify_parent(result,parent):
    for mode,diagnostic in result.items():
        expected=parent['metrics'][mode]['planes']
        for name,key in (('mse','surrogate_mse'),('signal_distortion','signal_distortion_mse'),('residual_noise','residual_injected_noise_mse'),('cross','cross_term')):
            if not np.allclose(diagnostic['full'][name],[p[key] for p in expected],atol=1e-10,rtol=1e-10):raise ValueError('Parent metric replay mismatch')


